    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_feeCalcSample_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.feeCalcSample()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05040.btn_feeCalcSample_onclick' }); }
};

