///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_excel = async function () {
    const sbmOptions = {
        id: "tx_fn_excel",
        method: "post",
        action: "/list/elwPage.do",
        ref: "dma_excelReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05040.tx_fn_excel" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/list/elwPage.do?method=elwFeeCalcExcelPrint", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.rules
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.rules = function () {
    /* sdd-asis-lifecycle:begin fn_rules — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (Promise.resolve($c.win.openPopup("/jldfil35709/jldfil35709.xml", { id: "elwCalRule", scrollbars: false, resizable: false, width: "570", height: "540", type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("elwCalRule"); this.closed = true; } });
    /* sdd-asis-lifecycle:end */
};


