    await $c.win.openPopup('/jldfil05011/jldfil05011.xml', { id: "elwExcelUploadPop", scrollbars: false, resizable: true, width: "610", height: "700", type: "pageFramePopup" }, { method: "elwFeeCalcUploadPop" });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.excel = async function () {
    /* sdd-asis-lifecycle:begin fn_excel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('dma_excelReq').get('rsltFlag') === "Y") {
        frm.action = '/list/elwPage.do';
        $c.util.getComponent('dma_excelReq').set('method', 'elwFeeCalcExcelDownload');
        await scwin.tx_fn_excel();
    } else {
        await $c.win.alert('계산된 결과가 없습니다.');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.print = async function () {
    /* sdd-asis-lifecycle:begin fn_print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.searchForm || { elements: [] });
    const popNm = "elwFeeCalcPrint";
    if ($c.util.getComponent('dma_excelReq').get('rsltFlag') === "Y") {
        $c.win.openPopup("", String('' || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, (typeof popNm !== 'undefined' ? popNm : '') ? Object.assign({ id: "elwFeeCalcPrint", scrollbars: true, resizable: true, width: "880", height: "600", type: "pageFramePopup" }, { id: (typeof popNm !== 'undefined' ? popNm : '') }) : { id: "elwFeeCalcPrint", scrollbars: true, resizable: true, width: "880", height: "600", type: "pageFramePopup" }), {});
        frm.target = popNm;
        frm.action = "/list/elwPage.do?method=elwFeeCalcExcelPrint";
        await scwin.tx_fn_print();
    } else {
        await $c.win.alert('계산된 결과가 없습니다.');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.reset
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reset = async function () {
    /* sdd-asis-lifecycle:begin fn_reset — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('dma_excelReq').get('rsltFlag') === "Y") {
        $c.util.getComponent('dma_excelReq').set('rsltFlag', "N");
        $c.util.getComponent("ipt_totFee").setValue("");
        ($c.util.getComponent("txt_feeCalcDivData") && $c.util.getComponent("txt_feeCalcDivData").setValue) ? $c.util.getComponent("txt_feeCalcDivData").setValue("") : (($c.util.getComponent("txt_feeCalcDivData") && $c.util.getComponent("txt_feeCalcDivData").setText) ? $c.util.getComponent("txt_feeCalcDivData").setText("") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "txt_feeCalcDivData"), void ("")));
        $c.util.getComponent('txt_feeCalcDivData').setStyle("display", "none");
        scwin.feeCalcDiv.setStyle("display", "");
    } else {
        await $c.win.alert('계산된 결과가 없습니다.');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setFeeCalcRslt
 * @author Inswave
 * @date 2026. 09. 29
 * @param pDataArr pIsuTotFee
 * @returns
 * @hidden N
*/
scwin.setFeeCalcRslt = function (pDataArr, pIsuTotFee) {
    /* sdd-asis-lifecycle:begin fn_setFeeCalcRslt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_excelReq').set('rsltFlag', "Y");
    let txt = "<table style=\"width:760px;\" class=\"table_board_default\" title=\"ELW 상장수수료 계산기 - 목록\" >";
    txt += "<colgroup>                               ";
    txt += "	<col width=\"60px\" />                 ";
    txt += "	<col width=\"140px\" />                ";
    txt += "	<col width=\"140px\" />                ";
    txt += "	<col width=\"140px\" />                ";
    txt += "	<col width=\"140px\" />                ";
    txt += "	<col width=\"140px\" />                ";
    txt += "</colgroup>                              ";
    txt += "<thead>                                  ";
    txt += "	<tr>                                   ";
    txt += "		<th class=\"subject\">번호</th>        ";
    txt += "		<th class=\"subject\">종목약명</th>      ";
    txt += "		<th class=\"subject\">발행수량</th>      ";
    txt += "		<th class=\"subject\">발행가액</th>      ";
    txt += "		<th class=\"subject\">발행총액</th>      ";
    txt += "		<th class=\"subject\">수수료</th>       ";
    txt += "	</tr>                                  ";
    for (let i = 0; i < pDataArr.length; i++) {
        txt += "<tr>";
        txt += "	<td id='tdNum' class='inputLeft_alignCenter' width='50'>" + (i + 1) + "</td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuAbbrv' class='form_search_no_border' readonly='readonly' size='40' value='" + pDataArr[i].isu_abbrv + "'/></td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuQty' class='form_search_money bd-none' readonly='readonly' size='16' value='" + pDataArr[i].isu_qty + "'/></td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuPrc' class='form_search_money bd-none' readonly='readonly' size='16' value='" + pDataArr[i].isu_prc + "'/></td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuTotamt' class='form_search_money bd-none' readonly='readonly' size='16' value='" + pDataArr[i].isu_totamt + "'/></td>";
        txt += "	<td class='inputLeft_alignCenter'><input type='text' name='isuFee' class='form_search_money bd-none' readonly='readonly' size='16' value='" + pDataArr[i].isu_fee + "'/></td>";
        txt += "</tr>";
    }
    const dataDiv = $c.util.getComponent("txt_feeCalcDivData");
    dataDiv.setStyle('width', "780px");
    dataDiv.setStyle('height', "320px");
    dataDiv.innerHTML = txt;
    scwin.feeCalcDiv.setStyle("display", "none");
    $c.util.getComponent('txt_feeCalcDivData').setStyle("display", "");
    $c.util.getComponent("ipt_totFee").setValue(pIsuTotFee);
    setTimeout(function() {
            $c.util.getComponent("dialogLoading").setStyle("display", "none");
        }, 800);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.numFormat
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.numFormat = async function (obj) {
    /* sdd-asis-lifecycle:begin numFormat — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ((obj.getValue() == null ? '' : String(obj.getValue())) !== '' && !$c.cm.isMinusNum(obj.getValue())) {
        obj.setValue("");
        await $c.win.alert("숫자만 입력가능합니다.");
        obj.focus();
        return;
    }
    if ((obj.getValue() == null ? '' : String(obj.getValue())) === '') {
        return;
    }
    if (isNaN(obj.getValue())) {
        obj.setValue("");
        return;
    }
    if (Number(obj.getValue()) > 999999999999999 || Number(obj.getValue()) < -999999999999999) {
        obj.setValue("");
        await $c.win.alert("입력한 숫자가 범위를 초과하였습니다.");
        obj.focus();
        return;
    }
    let str = Number(obj.getValue()) + "";
    let sMinusChar = "";
    if (Number(obj.getValue()) < 0) {
        str = str.substring(1);
        sMinusChar = "-";
    }
    let tempStr = str;
    let fltStr = "";
    if (str.indexOf(".") > -1) {
        tempStr = str.substr(0, str.indexOf("."));
        fltStr = str.substr(str.indexOf("."));
    }
    const leng = tempStr.length;
    const size = 3;
    const cnt = Math.floor(leng / size);
    const pos = leng % size;
    let result = "";
    if (cnt == 0) {
        obj.setValue(Number(obj.getValue()));
        return;
    }
    for (let i = cnt; i > 0; i = i - 1) {
        result = "," + tempStr.substr(pos + (i - 1) * size, size) + result;
    }
    if (result !== '') {
        if (pos == 0) {
            obj.setValue(sMinusChar + result.substring(1) + fltStr);
        } else {
            obj.setValue(sMinusChar + str.substr(0, pos) + result + fltStr);
        }
    }
    return;
    /* sdd-asis-lifecycle:end */
};
